import heapq

def find_the_city(n, edges, distance_threshold):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    def reachable_from(src):              # Dijkstra from src, counting cities within the threshold
        dist = [float("inf")] * n
        dist[src] = 0
        heap = [(0, src)]
        count = 0
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            if d > distance_threshold:
                break                     # everything left is even further
            if u != src:
                count += 1
            for v, w in adj[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return count

    answer, fewest = -1, float("inf")
    for i in range(n):
        reachable = reachable_from(i)
        if reachable <= fewest:           # <= so a tie goes to the larger city number
            answer, fewest = i, reachable
    return answer

