int reachableFrom(List<List<int[]>> adj, int n, int src, int limit) {   // Dijkstra, counting cities within limit
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[src] = 0;
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
    heap.add(new int[]{0, src});
    int count = 0;
    while (!heap.isEmpty()) {
        int[] top = heap.poll();
        int d = top[0], u = top[1];
        if (d > dist[u]) continue;
        if (d > limit) break;                            // everything left is even further
        if (u != src) count++;
        for (int[] e : adj.get(u)) {
            if (d + e[1] < dist[e[0]]) {
                dist[e[0]] = d + e[1];
                heap.add(new int[]{dist[e[0]], e[0]});
            }
        }
    }
    return count;
}

